// Общие шаги для экрана Reports → «Activity & usage» (/reports/usage), тикет #04d347 [F-16].
// Язык EN и компания «test» ставятся до загрузки страницы (startInTest); в конце теста — restoreTest (selected-company-id = test).
// Не сверено с сайтом при записи (правило проекта — не открывать сайт): разметка карточки счётчика
// (подпись и число в одном блоке — по скриншотам 04d347-*.png) и строки таблицы By person.
import { expect, Locator, Page, Response } from '@playwright/test';
export { TEST_COMPANY, restoreTest, startInTest, expectSelected } from '../multi-business/business-helpers';

export const USAGE_URL = '/reports/usage';

/** Владелец компании «test» — так он показан в By person (имени нет, только email; замечание 14.10). */
export const OWNER_EMAIL = 'iamdejar@gmail.com';

/** Подписи счётчиков (EN), порядок — как на экране. */
export const COUNTERS = [
  'Jobs created',
  'Jobs assigned',
  'Leads created',
  'Estimates created',
  'Invoices created',
  'Texts sent',
  'Calls started',
] as const;
export type Counter = (typeof COUNTERS)[number];

const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/** Ответ rpc usage_summary (сервер отдаёт данные экрана). */
export const isUsageSummary = (r: Response) => /usage_summary/i.test(r.url()) && r.request().method() !== 'OPTIONS';

/**
 * Открыть экран и дождаться данных: ответ usage_summary 200 и все счётчики на месте (скелетон пропал).
 * Возвращает статус ответа usage_summary.
 */
export async function openUsage(page: Page): Promise<number> {
  const summary = page.waitForResponse(isUsageSummary, { timeout: 45_000 });
  await page.goto(USAGE_URL);
  const status = (await summary).status();
  await expect(page.getByRole('heading', { name: 'Activity & usage' }).first()).toBeVisible({ timeout: 30_000 });
  await expect(counterCard(page, 'Calls started')).toBeVisible({ timeout: 30_000 });
  return status;
}

/** Нажать Refresh и дождаться нового ответа usage_summary. */
export async function refreshUsage(page: Page): Promise<number> {
  const summary = page.waitForResponse(isUsageSummary, { timeout: 45_000 });
  await page.getByRole('button', { name: 'Refresh', exact: true }).click();
  return (await summary).status();
}

/** Карточка счётчика: самый внутренний блок, где есть подпись и число. */
export function counterCard(page: Page, label: Counter): Locator {
  return page.locator('main div')
    .filter({ has: page.getByText(label, { exact: true }) })
    .filter({ hasText: new RegExp(`${esc(label)}[\\s\\S]*\\d`) })
    .last();
}

/** Число в карточке счётчика (целое ≥ 0). Падает, если числа нет. */
export async function counterValue(page: Page, label: Counter): Promise<number> {
  const text = (await counterCard(page, label).innerText()).replace(label, '');
  const m = text.match(/\d[\d,]*/);
  expect(m, `в карточке «${label}» есть число: «${text.trim()}»`).not.toBeNull();
  return Number(m![0].replace(/,/g, ''));
}

export async function allCounters(page: Page): Promise<Record<Counter, number>> {
  const out = {} as Record<Counter, number>;
  for (const c of COUNTERS) out[c] = await counterValue(page, c);
  return out;
}

/** Блок «By person»: заголовок + таблица Person / Events. */
export function byPersonBlock(page: Page): Locator {
  return page.locator('main div')
    .filter({ has: page.getByText('By person', { exact: true }) })
    .filter({ hasText: /Person[\s\S]*Events/ })
    .last();
}

/** Строка By person по тексту первой колонки → число Events. */
export async function byPersonEvents(block: Locator, who: string | RegExp): Promise<number> {
  const name = typeof who === 'string' ? new RegExp(`^\\s*${esc(who)}\\s*$`) : who;
  const row = block.locator('tr, li, div').filter({ has: block.getByText(name) }).filter({ hasText: /\d\s*$/ }).last();
  await expect(row, `строка By person «${who}»`).toBeVisible();
  const m = (await row.innerText()).match(/(\d[\d,]*)\s*$/);
  expect(m, `число Events в строке «${who}»`).not.toBeNull();
  return Number(m![1].replace(/,/g, ''));
}

/** Сумма Events по всем строкам By person (последнее число каждой строки таблицы). */
export async function byPersonTotal(block: Locator): Promise<number> {
  const rows = await block.getByRole('row').allInnerTexts();
  const nums = rows.map((t) => t.match(/(\d[\d,]*)\s*$/)?.[1]).filter((n): n is string => !!n).map((n) => Number(n.replace(/,/g, '')));
  expect(nums.length, 'в By person есть строки с числом Events').toBeGreaterThan(0);
  return nums.reduce((a, b) => a + b, 0);
}

/** Ожидаемый диапазон «This month»: «Oct 1 – Oct 18, 2026» (время раннера). */
export function thisMonthRange(now = new Date()): RegExp {
  const mon = now.toLocaleString('en-US', { month: 'short' });
  return new RegExp(`${mon} 1\\s*[–-]\\s*${mon} ${now.getDate()}, ${now.getFullYear()}`);
}

/** Проверка общей части экрана: период This month, 7 числовых счётчиков, Per day, By person с владельцем. */
export async function expectUsageScreen(page: Page) {
  // Период по умолчанию — «This month» (источник: сценарий тикета — «פעילות ושימוש», период «החודש»).
  await expect(page.getByText('This month', { exact: true }).first()).toBeVisible();
  await expect(page.locator('main')).toContainText(thisMonthRange());

  // Счётчики по типам (источник: DoD «צבירה למונים מוצגת במסך אנליטיקס»).
  const values = await allCounters(page);
  for (const c of COUNTERS) expect(Number.isInteger(values[c]) && values[c] >= 0, `${c} = ${values[c]}`).toBe(true);

  // График по дням и разбивка по людям (комментарий программиста к #04d347).
  await expect(page.getByText('Per day', { exact: true })).toBeVisible();
  const people = byPersonBlock(page);
  await expect(people).toBeVisible();
  expect(await byPersonEvents(people, OWNER_EMAIL)).toBeGreaterThan(0);
  await byPersonEvents(people, 'Earlier records');
  return { values, people };
}
